"""Staircase recognition and decoding: read (b, j) off an integer in O(log k) bit operations."""

from __future__ import annotations

from typing import Optional, Tuple


def two_adic_valuation(k: int) -> int:
    """Exponent of 2 in k > 0, i.e. the length of the trailing zero block."""
    return (k & -k).bit_length() - 1


def decode_staircase(k: int) -> Optional[Tuple[int, int]]:
    """Return (b, j) with k = 2^b (2^j - 1), or None if k has no staircase form.

    Correctness: the parametrisation is a normal form -- b is the 2-adic valuation
    of k and j is its binary digit sum -- so the pair is unique when it exists.
    The test 'm + 1 is a power of two' is the statement that the odd part of k is
    a Mersenne number 2^j - 1.
    """
    if k <= 0:
        return None
    b = two_adic_valuation(k)
    m = k >> b
    if (m + 1) & m == 0:
        return b, (m + 1).bit_length() - 1
    return None


def describe(k: int) -> str:
    d = decode_staircase(k)
    if d is None:
        return f"{k} = {k:b}_2 is not a staircase number"
    b, j = d
    return (
        f"{k} = {k:b}_2 = st({b},{j}) = 2^{b + j} - 2^{b}; "
        f"width {b + j}, top point {2 ** (b + j)}, "
        f"fraction {(2 ** j - 1)}/{2 ** j} of it"
    )


if __name__ == "__main__":
    for k in (96, 112, 128, 120, 21, 1000, 2 ** 20 - 2 ** 13):
        print(describe(k))
